          { name: { $regex: rawQuery, $options: 'i' } },
          { genericName: { $regex: rawQuery, $options: 'i' } },
          { registrationNumber: { $regex: `^${rawQuery}$`, $options: 'i' } },
          { barcode: { $regex: `^${rawQuery}$`, $options: 'i' } },
          { manufacturer: { $regex: rawQuery, $options: 'i' } },
